const s = wb.getWorksheet('Edit');
const h = '--$F$1:$AT$1', r = '$F2:$AT2';
const finish = (st:string) => `=IF(${st}2="","",AGGREGATE(14,6,${h}/((${r}="m")*(${h}<IFERROR(AGGREGATE(15,6,${h}/((${r}<>"m")*(${h}>${st}2)),1),9))),1))`;
for (let n=2;n<=16;n++){
  const f=(x:string)=>x.replace(/\$F2:\$AT2/g,`$F${n}:$AT${n}`).replace(/\b([BCD])2\b/g,`$1${n}`);
  wb.getRange(`Edit!B${n}`).setValue(f(`=IFERROR(AGGREGATE(15,6,${h}/(${r}="m"),1),"")`));
  wb.getRange(`Edit!C${n}`).setValue(f(finish('B')));
  wb.getRange(`Edit!D${n}`).setValue(f(`=IF(C2="","",IFERROR(AGGREGATE(15,6,${h}/((${r}="m")*(${h}>C2)),1),""))`));
  wb.getRange(`Edit!E${n}`).setValue(f(finish('D')));
}
log(wb.getRange('Edit!B2').getFormula?.());
log(wb.getRange('Edit!E16').getFormula?.());
wb.getRange('Edit!A1:E16')

